package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

// NetworkBase carries the radio model, the resource accounting and the
// market. Every contract embeds it, so every contract exposes the same set
// of network operations without the code being repeated.
type NetworkBase struct {
    contractapi.Contract
}

// GenericRecord is the part of a written record that the shared code needs
// to read back. Each contract writes its own record type — Assignment,
// Bandwidth, SignalStrengthRecord and so on — and those differ, but every
// one of them carries the serving cell. Decoding into this minimal shape
// works for all of them, because encoding/json ignores fields it does not
// recognise. That is what lets Release live here rather than being
// duplicated into all 34 contracts.
type GenericRecord struct {
    ServingCell string `json:"servingCell"`
    GrantedHz   int64  `json:"grantedHz"`
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    ChannelIndex    int64  `json:"channelIndex"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    QosPriceMicro         int64  `json:"qosPriceMicro"`

    // Frequency reuse. TotalBandwidthHz is the licensed block; dividing it
    // is what a reuse plan does, so it is remembered separately from the
    // per-cell figure that ReuseChannels writes.
    TotalBandwidthHz      int64  `json:"totalBandwidthHz"`
    ChannelCount          int64  `json:"channelCount"`
    BaseFreqMHz           int64  `json:"baseFreqMHz"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// ReusePlan describes how the band is divided across cells.
type ReusePlan struct {
    TotalBandwidthHz int64               `json:"totalBandwidthHz"`
    ChannelCount     int64               `json:"channelCount"`
    PerChannelHz     int64               `json:"perChannelHz"`
    Cells            []ChannelAssignment `json:"cells"`
}

// ChannelAssignment is one cell's place in the plan.
type ChannelAssignment struct {
    AntennaID    string `json:"antennaID"`
    ChannelIndex int64  `json:"channelIndex"`
    FreqMHz      int64  `json:"freqMHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    AllocatedHz  int64  `json:"allocatedHz"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Tier          int64  `json:"qosTier"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultEntityTxMilliDbm = int64(23000) // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *NetworkBase) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            ChannelIndex:    0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultEntityTxMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        QosPriceMicro:         defaultQosPrice,
        TotalBandwidthHz:      defaultBandwidthHz,
        ChannelCount:          1,
        BaseFreqMHz:           defaultFreqMHz,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *NetworkBase) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *NetworkBase) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *NetworkBase) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *NetworkBase) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPower changes a cell's transmit power.
//
// TxPowerMilliDbm was fixed at 46 dBm for every cell and nothing could
// alter it, so LocationBasedPowerManagement recorded a power level the
// propagation model never read. Power set here feeds straight into RSSI:
// raising it extends reach and raises interference for neighbours on the
// same channel, which is the trade-off power control exists to manage.
func (s *NetworkBase) SetPower(ctx contractapi.TransactionContextInterface, antennaID, txPowerMilliDbm string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    p := parseIntOr(txPowerMilliDbm, a.TxPowerMilliDbm)
    // Below 0 dBm a macrocell serves nobody; above 60 dBm is beyond what
    // regulators allow for terrestrial cellular.
    if p < 0 || p > 60000 {
        return fmt.Errorf("transmit power must be between 0 and 60000 milli-dBm, got %d", p)
    }
    a.TxPowerMilliDbm = p
    return s.saveAntenna(ctx, &a)
}

// SetChannel assigns a cell to a frequency channel.
//
// Cells on different channels do not interfere. With eight cells and four
// channels a reuse pattern leaves at most one co-channel neighbour instead
// of seven, which lifts SINR sharply — at the cost of each channel serving
// fewer cells. This is frequency reuse, and it is the other half of what
// LocationBasedChannelAllocation was recording without effect.
func (s *NetworkBase) SetChannel(ctx contractapi.TransactionContextInterface, antennaID, channelIndex, freqMHz string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.ChannelIndex = parseIntOr(channelIndex, a.ChannelIndex)
    if a.ChannelIndex < 0 || a.ChannelIndex > 63 {
        return fmt.Errorf("channelIndex must be between 0 and 63, got %d", a.ChannelIndex)
    }
    f := parseIntOr(freqMHz, a.FreqMHz)
    if f < 400 || f > 100000 {
        return fmt.Errorf("frequency must be between 400 and 100000 MHz, got %d", f)
    }
    a.FreqMHz = f

    // Moving one cell onto an existing channel does not change how the band
    // is divided, so its width follows the plan rather than staying at
    // whatever it was.
    cfg, cerr := s.loadConfig(ctx)
    if cerr == nil && cfg.ChannelCount > 1 && cfg.TotalBandwidthHz > 0 {
        perChannel := cfg.TotalBandwidthHz / cfg.ChannelCount
        if a.AllocatedHz > perChannel {
            return fmt.Errorf(
                "cell %s has %d Hz committed, more than the %d Hz this plan allows",
                antennaID, a.AllocatedHz, perChannel)
        }
        a.BandwidthHz = perChannel
    }
    return s.saveAntenna(ctx, &a)
}

// ReuseChannels lays out a frequency reuse plan across n channels.
//
// The band is finite, so splitting it into n channels leaves each cell with
// TotalBandwidthHz / n. Handing every cell the full band on a different
// channel would be free interference relief, which no real deployment gets:
// spectrum is licensed as one block and reuse divides it.
//
// The trade-off this creates is the real one operators face:
//
//   more channels → fewer co-channel neighbours → higher SINR
//                 → narrower cells → fewer entities served, lower peak rate
//
// A third effect runs alongside and is easy to miss: a narrower channel has
// a lower thermal noise floor, 3 dB per halving. So SINR gains from two
// directions at once — less interference and less noise — while capacity
// loses from one. Shannon is logarithmic in SINR but linear in bandwidth,
// so beyond a certain point the loss wins. Finding that point is the
// experiment.
//
// TotalBandwidthHz is remembered on the config so repeated calls divide the
// original band rather than dividing what a previous call already halved.
func (s *NetworkBase) ReuseChannels(ctx contractapi.TransactionContextInterface, channelCount string) error {
    n := parseIntOr(channelCount, 1)
    if n < 1 || n > 64 {
        return fmt.Errorf("channelCount must be between 1 and 64, got %d", n)
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    if n > int64(len(antennas)) {
        return fmt.Errorf(
            "%d channels across %d cells leaves channels unused — use at most %d",
            n, len(antennas), len(antennas))
    }

    // The first call establishes the band being divided.
    if cfg.TotalBandwidthHz <= 0 {
        cfg.TotalBandwidthHz = defaultBandwidthHz
    }
    perChannel := cfg.TotalBandwidthHz / n
    if perChannel < 200000 {
        return fmt.Errorf(
            "%d channels would leave %d Hz per cell, below the 200 kHz floor",
            n, perChannel)
    }

    // Spectrum already committed cannot exceed the narrower channel.
    for _, a := range antennas {
        if a.AllocatedHz > perChannel {
            return fmt.Errorf(
                "cell %s has %d Hz committed, more than the %d Hz a %d-channel plan allows — release grants first",
                a.AntennaID, a.AllocatedHz, perChannel, n)
        }
    }

    for i, a := range antennas {
        a.ChannelIndex = int64(i) % n
        a.BandwidthHz = perChannel
        // Frequencies sit side by side across the band, so neighbouring
        // channel indices are neighbouring frequencies — which is what a
        // reuse plan assigns to cells that are far apart.
        a.FreqMHz = cfg.BaseFreqMHz + (a.ChannelIndex*perChannel)/1000000
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }

    cfg.ChannelCount = n
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SpectrumPlan reports the reuse layout: how the band is divided, which
// cell is on which channel, and how much of each is committed.
func (s *NetworkBase) SpectrumPlan(ctx contractapi.TransactionContextInterface) (*ReusePlan, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    total := cfg.TotalBandwidthHz
    if total <= 0 {
        total = defaultBandwidthHz
    }
    count := cfg.ChannelCount
    if count < 1 {
        count = 1
    }

    plan := ReusePlan{
        TotalBandwidthHz: total,
        ChannelCount:     count,
        PerChannelHz:     total / count,
        Cells:            make([]ChannelAssignment, 0, len(antennas)),
    }
    for _, a := range antennas {
        plan.Cells = append(plan.Cells, ChannelAssignment{
            AntennaID:    a.AntennaID,
            ChannelIndex: a.ChannelIndex,
            FreqMHz:      a.FreqMHz,
            BandwidthHz:  a.BandwidthHz,
            AllocatedHz:  a.AllocatedHz,
        })
    }
    return &plan, nil
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *NetworkBase) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *NetworkBase) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *NetworkBase) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *NetworkBase) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *NetworkBase) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *NetworkBase) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *NetworkBase) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}





func (s *NetworkBase) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *NetworkBase) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *NetworkBase) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *NetworkBase) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    // 0 keeps the existing behaviour: the rate follows the cell's band
    // unless spectrum accounting is on.
    return s.evaluateWithShare(antennas, cfg, entityID, x, y, 0)
}

// evaluateWithShare is evaluate with an explicit spectrum slice, so a
// purchased QoS tier can widen it.
func (s *NetworkBase) evaluateWithShare(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y, requestHz int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        // requestHz of 0 means "whatever the cell offers" — the default when
        // spectrum is not being accounted for. A positive value is a slice
        // the caller insists on, which is how RelayFor prices both sides of
        // a deal on the same scale: without it the direct path was measured
        // against 20 MHz while the device-to-device hop was measured against
        // 100 kHz, and every deal was refused for costing more than it saved.
        //
        // Note this parameter used to be ignored entirely — the body read
        // cfg.RequestHz and only when tracking was on, so passing a share in
        // did nothing at all.
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if requestHz > 0 {
            rateBandwidth = requestHz
        }
        if cfg.TrackBandwidth {
            granted = requestHz
            if granted <= 0 {
                granted = cfg.RequestHz
            }
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = granted
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// effectiveHz resolves a possibly-zero spectrum share against the
// configured one. Callers pass 0 to mean "whatever the cell offers", which
// evaluateWithShare understands, but the admission check needs a concrete
// figure to compare against the cell's free band.
func effectiveHz(cfg *NetworkConfig, requestHz int64) int64 {
    if requestHz > 0 {
        return requestHz
    }
    return cfg.RequestHz
}


// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *NetworkBase) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *NetworkBase) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }

    // A purchased tier widens the slice this entity is evaluated against,
    // so the rate it sees reflects what it paid for.
    requestHz := int64(0)
    tier := int64(0)
    if cfg.TrackBandwidth {
        requestHz = cfg.RequestHz
        q, qerr := s.qosOf(ctx, entityID)
        if qerr != nil {
            return nil, nil, qerr
        }
        if q.Tier > 0 {
            tier = q.Tier
            requestHz = tierShareHz(q.Tier, cfg.RequestHz)
        }
    }

    reports, cells, err := s.evaluateWithShare(antennas, cfg, entityID, x, y, requestHz)
    if err != nil {
        return nil, nil, err
    }
    for _, r := range reports {
        r.Tier = tier
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+effectiveHz(cfg, requestHz) > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, effectiveHz(cfg, requestHz))
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *NetworkBase) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *NetworkBase) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *NetworkBase) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *NetworkBase) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec GenericRecord
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"   // relay deals
    grantPrefix   = "~GRANT:"
    // The price of one QoS tier. Defined here beside the other market
    // constants, though NetworkConfig — written by the network block — is
    // what reads it: Go compiles both blocks into one package, so where a
    // constant is declared does not matter, only that it is declared once.
    defaultQosPrice    = int64(50000)  // 0.05 coin per tier
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *NetworkBase) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64, cfg *NetworkConfig) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        // A wallet opens at first touch with a starting balance, the same way
        // energyOf hands out a full battery. Without it, benchmarking any
        // paying operation measured "insufficient funds" rather than the
        // operation itself — a cold BuyQos could never succeed, because the
        // account it charges had never been minted into.
        //
        // Only stripe 0 carries the opening balance, so BalanceOf still sums
        // to one starting balance rather than one per stripe.
        opening := int64(0)
        if stripe == 0 {
            opening = cfg.InitialBalanceMicro
        }
        return &Account{AccountID: accountID, Balance: opening}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *NetworkBase) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *NetworkBase) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st, cfg)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *NetworkBase) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st, cfg)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf(
        "%s cannot cover %d micro-tokens across %d stripes — an account opens with %d, so this has been spent",
        accountID, amount, cfg.Stripes, cfg.InitialBalanceMicro)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *NetworkBase) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *NetworkBase) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st, cfg)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *NetworkBase) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *NetworkBase) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *NetworkBase) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *NetworkBase) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *NetworkBase) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        if g.HeldHz == 0 {
            return fmt.Errorf(
                "%s holds no spectrum to sublet: a grant is issued when an entity is admitted, and only while spectrum accounting is on — call SetResources with trackBandwidth on, then admit %s before it can sell",
                from, from)
        }
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── quality of service ────────────────────────────────────────────────
   The one thing a user can buy that the contract can actually deliver.

   Energy and computation were tried here and removed: a ledger entry
   moving microjoules between two batteries has no physical counterpart —
   devices do not charge each other — and proof-of-work rewards effort
   rather than useful output, which belongs to public-chain mining and not
   to a permissioned network with endorsement consensus.

   Priority is different. The contract itself decides which entity gets a
   cell when spectrum is short, so a priority it sells is a priority it
   enforces. Three tiers, each buying a larger share of the cell and a
   claim ahead of lower tiers when the cell fills.                        */

// QosTier is what an entity has bought. Held per entity, so purchases
// never contend with one another.
type QosTier struct {
    EntityID    string `json:"entityID"`
    Tier        int64  `json:"tier"`          // 0 best-effort, 1 standard, 2 premium
    ShareHz     int64  `json:"shareHz"`       // spectrum this tier grants
    PaidMicro   int64  `json:"paidMicro"`
    ExpiresAt   int64  `json:"expiresAtBlock"`
    Timestamp   string `json:"timestamp"`
}

const qosPrefix = "~QOS:"

// tierShareHz is the spectrum a tier is entitled to, as a multiple of the
// base grant: best-effort takes the base, standard twice, premium four
// times. A premium entity therefore reaches roughly twice the rate of a
// standard one at the same SINR — Shannon is logarithmic in power but
// linear in bandwidth, so the gain here is real and proportional.
func tierShareHz(tier, baseHz int64) int64 {
    switch tier {
    case 2:
        return baseHz * 4
    case 1:
        return baseHz * 2
    default:
        return baseHz
    }
}

func (s *NetworkBase) qosOf(ctx contractapi.TransactionContextInterface, entityID string) (*QosTier, error) {
    b, err := ctx.GetStub().GetState(qosPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &QosTier{EntityID: entityID, Tier: 0}, nil
    }
    var q QosTier
    if err := json.Unmarshal(b, &q); err != nil {
        return nil, err
    }
    return &q, nil
}

// QosOf reports an entity's tier.
func (s *NetworkBase) QosOf(ctx contractapi.TransactionContextInterface, entityID string) (*QosTier, error) {
    return s.qosOf(ctx, entityID)
}

// BuyQos purchases a service tier.
//
// The price is charged to the buyer's own account and credited to the
// operator of the cell it is attached to — so this is the one market
// mechanism with a shared-key write on the receiving side. That is
// deliberate: it makes the contrast with the peer-to-peer mechanisms
// measurable rather than assumed.
func (s *NetworkBase) BuyQos(ctx contractapi.TransactionContextInterface, entityID, tier string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    t, err := strconv.ParseInt(tier, 10, 64)
    if err != nil || t < 0 || t > 2 {
        return fmt.Errorf("tier must be 0, 1 or 2, got %q", tier)
    }

    price := cfg.QosPriceMicro * t
    if price > 0 {
        if err := s.debit(ctx, entityID, price, cfg); err != nil {
            return fmt.Errorf("cannot pay for tier %d: %v", t, err)
        }
    }

    q := QosTier{
        EntityID:  entityID,
        Tier:      t,
        ShareHz:   tierShareHz(t, cfg.RequestHz),
        PaidMicro: price,
        Timestamp: txTimestamp(ctx),
    }
    b, err := json.Marshal(&q)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(qosPrefix+entityID, b)
}

// SellQos drops back to best-effort and refunds nothing — the tier was
// consumed while it was held.
func (s *NetworkBase) SellQos(ctx contractapi.TransactionContextInterface, entityID string) error {
    return ctx.GetStub().DelState(qosPrefix + entityID)
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *NetworkBase) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    // Both cellular links are measured against the entity's own slice, the
    // same width the device-to-device hop below uses. Evaluating them at the
    // cell's full band — which is what evaluate does while spectrum
    // accounting is off — made the direct path look almost free next to a
    // hop priced on 100 kHz, so every deal was refused for costing more than
    // it saved. Relay economics is a comparison, and a comparison needs both
    // sides on the same scale.
    edgeReports, _, err := s.evaluateWithShare(antennas, cfg, edgeEntity, ex, ey, cfg.RequestHz)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluateWithShare(antennas, cfg, relayEntity, rx, ry, cfg.RequestHz)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    // Noise scales with the bandwidth actually occupied, and a device-to-
    // device hop occupies the entity's slice — not the cell's whole band.
    // Measuring it against 20 MHz overstated the noise floor by 23 dB and
    // made every hop beyond a few hundred metres carry no usable rate, so
    // no relay deal could ever clear.
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(cfg.RequestHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *NetworkBase) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *NetworkBase) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   qosPrice    cost of one service tier, in micro-tokens
func (s *NetworkBase) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, qosPrice string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.QosPriceMicro = parseIntOr(qosPrice, cfg.QosPriceMicro)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

SHARED_EOF

    (
      cd chaincode/$contract
      if [ ! -f go.mod ]; then
          go mod init $contract >/dev/null 2>&1
      fi
      go mod edit -require=github.com/hyperledger/fabric-contract-api-go@v1.2.1
      go mod tidy >/dev/null 2>&1
      go mod vendor >/dev/null 2>&1
    )
done

# Compile one contract before declaring success.
#
# Every contract shares the same shared.go, so if one builds they all do —
# and if one does not, deploying is a waste of several minutes that ends in
# "0/4 committed" with the real cause buried in a build log. The structural
# check catches a lot but it is not a compiler, and four separate rounds of
# this project ended with a compile error reaching the network.
FIRST="${contracts[0]}"
if command -v go >/dev/null 2>&1 && [ -d "chaincode/$FIRST" ]; then
    echo ""
    echo "Compiling $FIRST as a check..."
    if (cd "chaincode/$FIRST" && go build ./... 2>&1); then
        echo "  build OK — the shared code compiles, so every contract does"
        rm -f "chaincode/$FIRST/$FIRST" 2>/dev/null
    else
        echo ""
        echo "  BUILD FAILED. The contracts were written but will not deploy." >&2
        echo "  Fix the error above before running deploy-staged.sh." >&2
        exit 1
    fi
fi

echo "Regenerated ${#contracts[@]} of ${#ALL_CONTRACTS[@]} location-aware contracts in $SCRIPT_DIR/chaincode"
for contract in "${contracts[@]}"; do
    if [ -f "chaincode/$contract/chaincode.go" ]; then
        echo " - $contract: OK"
    else
        echo " - $contract: Failed"
    fi
done
